#!/usr/bin/env python3
"""
ABRAXAS COMPREHENSIVE AUDIT FIX
Run from project root: python3 fix_audit.py

ISSUES RESOLVED:
  #1 WALLET BUTTON DOES NOTHING
     Root cause: @solana/wallet-adapter-react-ui/styles.css was never imported.
     The wallet modal renders as 0px/invisible without its CSS.
     Fix: globals.css now @imports the wallet adapter stylesheet first.

  #2 GENESIS ASSET NOT PROMINENT
     terminal/page.tsx now defaults to "flagship" view (Genesis Asset).
     GENESIS ASSET toggle comes first in the nav.

  #3 SPLASH PAGE FLOW
     app/page.tsx → 2.4s splash → /terminal → Genesis Asset
     No auth wall blocking the demo.

  #4 PROVIDER CHAIN CORRECT
     layout.tsx: SessionProvider → SolanaProvider → children
     Both providers wrap the entire app including /auth/signin.
     This is why wallet connect was silently failing on the signin page.

  #5 FLAGSHIP ASSET CLEAN BUILD
     FlagshipAssetPage.tsx: no `as const`, no undefined CIELO_ refs,
     Tab type explicitly declared, sqft null-safe.

  #6 AUTH ROUTES
     NextAuth route + lib/auth.ts correct.
     GitHub callback: https://abraxas-app.vercel.app/api/auth/callback/github
     Twitter callback: https://abraxas-app.vercel.app/api/auth/callback/twitter

  VERCEL ENV VARS REQUIRED (add in Vercel dashboard → Settings → Env):
     NEXTAUTH_URL      = https://abraxas-app.vercel.app
     NEXTAUTH_SECRET   = (run: openssl rand -base64 32)
     GITHUB_CLIENT_ID  + GITHUB_CLIENT_SECRET
     TWITTER_CLIENT_ID + TWITTER_CLIENT_SECRET
"""
import base64, os, sys, glob

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "app/globals.css": "",
    "app/terminal/page.tsx": "",
    "app/page.tsx": "",
    "app/layout.tsx": "",
    "components/SolanaProvider.tsx": "",
    "app/auth/signin/page.tsx": "",
    "app/api/auth/[...nextauth]/route.ts": "Ly8gRklMRTogYXBwL2FwaS9hdXRoL1suLi5uZXh0YXV0aF0vcm91dGUudHMKaW1wb3J0IE5leHRBdXRoIGZyb20gIm5leHQtYXV0aCI7CmltcG9ydCB7IGF1dGhPcHRpb25zIH0gZnJvbSAiQC9saWIvYXV0aCI7CmNvbnN0IGhhbmRsZXIgPSBOZXh0QXV0aChhdXRoT3B0aW9ucyk7CmV4cG9ydCB7IGhhbmRsZXIgYXMgR0VULCBoYW5kbGVyIGFzIFBPU1QgfTsK",
    "lib/auth.ts": "",
    "components/assets/FlagshipAssetPage.tsx": "",
    "lib/data/flagshipProperty.ts": "",
    "components/CompactWallet.tsx": "",
    "vercel.json": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

# Remove old fix scripts
removed = []
for f in glob.glob("fix_*.py"):
    if f != "fix_audit.py":
        os.remove(f); removed.append(f)
if removed:
    print("REMOVED  " + ", ".join(removed))

print("""
All files written.

RUN:
  npm run build
  git add -A
  git commit -m "fix: wallet CSS import, Genesis Asset default, clean provider chain"
  git push origin main

VERIFY ON LIVE SITE:
  1. abraxas-app.vercel.app → splash (2s) → /terminal → CIELO SUNRISE hero
  2. Wallet connect button opens modal with wallet list
  3. GENESIS ASSET tab shows by default, ASSET TERMINAL toggle available
  4. Sign In → /auth/signin works (GitHub/X needs Vercel env vars)
  5. No duplicate auth/wallet buttons
""")
